entries[126927] = { ["name"] = "Recipe: Sugar-Crusted Fish Feast", ["text"] = "Binds when picked up\nUse: Teaches you how to cook a Sugar-Crusted Fish Feast.\nRequires Classic Cooking (150)\nSell Price:\nSugar-Crusted Fish Feast\nUse: Set out a great feast that will feed your party!\n\nRestores 10% of health and mana every second for 10 sec and you will become Well Fed, increasing Versatility for 20 min. Cannot be consumed by players above level 50.\nSell Price:\nRequires Darkmoon Daggermaw (5)" }
entries[126928] = { ["name"] = "Recipe: Lemon Herb Filet", ["text"] = "Use: Teaches you how to cook Lemon Herb Filet.\nRequires Classic Cooking (1)\nSell Price:\nLemon Herb Filet\nUse: Restores 10% of your health and mana per second for 10 sec and you will become Well Fed, increasing Versatility for 20 min. Must remain seated while eating. Ineffective over level 50.\nSell Price:\nRequires Darkmoon Daggermaw (2)" }
entries[126929] = { ["name"] = "Recipe: Fancy Darkmoon Feast", ["text"] = "Binds when picked up\nUse: Teaches you how to cook a Fancy Darkmoon Feast.\nRequires Classic Cooking (225)\nSell Price:\nFancy Darkmoon Feast\nUse: Set out a great feast that will feed your party and dress them fancily! Restores 10% of health and mana every second for 10 sec and you will become Well Fed, increasing Versatility for 20 min. Cannot be consumed by players above level 50.\nSell Price:\nRequires Darkmoon Daggermaw (10)" }
