entries[127010] = { ["name"] = "Pristine Lightforge Breastplate", ["text"] = "Heirloom Upgrade Level: 0/0\nBinds to Warband\nChest Plate\n34 Armor\n+10 [Strength or Intellect]\n+15 Stamina\n+ 20 Haste\nRequires level 1 to 29 ( 29)\n\nRegalia of Fabled Adventurers (0/7)\nHeirloom Chestpiece\nHeirloom Helm\nHeirloom Shoulders\nHeirloom Cloak\nHeirloom Legs\nHeirloom Necklace\nHeirloom Ring\n(2) Set : Rested experience consumed is reduced by 30%.\n(3) Set : Increases your out-of-combat regeneration in the outdoors, normal dungeons and battlegrounds.\n(5) Set : Gaining a level triggers Burst of Knowledge, dealing 1126 Holy damage to nearby enemies and granting you 40% Primary Stat for 2 min. Defeating enemies extends this effect, up to an additional 2 min.\n(6) Set : Rested experience consumed is reduced by an additional 30%.\n\nVendor:\nEstelle Gendry\nZone:\nOrgrimmar - Gates of Orgrimmar\n\nVendor:\nKrom Stoutarm\nZone:\nIronforge - Hall of Explorers" }
entries[127011] = { ["name"] = "Pristine Lightforge Legplates", ["text"] = "Heirloom Upgrade Level: 0/0\nBinds to Warband\nLegs Plate\n30 Armor\n+10 [Strength or Intellect]\n+15 Stamina\n+ 10 Critical Strike\n+ 10 Haste\nRequires level 1 to 29 ( 29)\n\nRegalia of Fabled Adventurers (0/7)\nHeirloom Chestpiece\nHeirloom Helm\nHeirloom Shoulders\nHeirloom Cloak\nHeirloom Legs\nHeirloom Necklace\nHeirloom Ring\n(2) Set : Rested experience consumed is reduced by 30%.\n(3) Set : Increases your out-of-combat regeneration in the outdoors, normal dungeons and battlegrounds.\n(5) Set : Gaining a level triggers Burst of Knowledge, dealing 1126 Holy damage to nearby enemies and granting you 40% Primary Stat for 2 min. Defeating enemies extends this effect, up to an additional 2 min.\n(6) Set : Rested experience consumed is reduced by an additional 30%.\n\nVendor:\nGoram\nZone:\nOrgrimmar - Valley of Strength\n\nVendor:\nShay Pressler\nZone:\nStormwind - Trade District" }
