entries[127022] = { ["name"] = "Pattern: Imbued Silkweave Cinch", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Teaches you how to make an Imbued Silkweave Cinch.\nCraft an Imbued Silkweave Cinch.\nRequires Legion Tailoring (1)\n\nImbued Silkweave Cinch\nBinds when equipped\nWaist Cloth\n3 Armor\n+4 Intellect\n+6 Stamina\nDurability 55 / 55\nSell Price:\nRequires Imbued Silkweave (12), Unbroken Tooth (20), Blood of Sargeras (3)" }
