entries[127049] = { ["name"] = "Gladiator's Dreadplate Chestpiece", ["text"] = "Warlords Season 1\nBinds when picked up\nChest Plate\n17 Armor\n+5 [Strength or Intellect]\n+7 Stamina\n+ 5 Critical Strike\n+ 5 Haste\nClasses: Death Knight\nRequires any Horde race\nGladiator's Desecration (0/5)\nGladiator's Dreadplate Chestpiece\nGladiator's Dreadplate Helm\nGladiator's Dreadplate Gauntlets\nGladiator's Dreadplate Shoulders\nGladiator's Dreadplate Legguards\n(2) Set Blood: Using Death Grip increases the damage of your next weapon special attack by 25%. (2) Set Frost: Using Death Grip increases the damage of your next weapon special attack by 25%. (2) Set Unholy: Using Death Grip increases the damage of your next weapon special attack by 25%.\n(4) Set Blood: Anti-Magic Shell also applies to the nearest ally.\n(4) Set Frost: When you have Rime active, your next Howling Blast will increase Frost damage taken on all targets by 10% for 8 sec.\n(4) Set Unholy: When you activate Dark Transformation, your Shadow damage dealt is increased by 20% for 15 sec.\nSell Price:" }
entries[127050] = { ["name"] = "Gladiator's Chain Armor", ["text"] = "Warlords Season 1\nBinds when picked up\nChest Mail\n11 Armor\n+5 [Agility or Intellect]\n+7 Stamina\n+ 5 Critical Strike\n+ 5 Haste\nClasses: Hunter\nRequires any Horde race\nGladiator's Pursuit (0/5)\nGladiator's Chain Armor\nGladiator's Chain Helm\nGladiator's Chain Gauntlets\nGladiator's Chain Spaulders\nGladiator's Chain Leggings\nLegacy Set: Bonus is inactive\n(2) Set Beast Mastery: Increases the duration of [ Wing Clip / Concussive Shot] by 2 sec. (2) Set Marksmanship: Increases the duration of [ Wing Clip / Concussive Shot] by 2 sec. (2) Set Survival: Increases the duration of [ Wing Clip / Concussive Shot] by 2 sec.\n(4) Set Beast Mastery: You and your pet share diminishing returns from crowd control effects.\n(4) Set Marksmanship: Aimed Shot reduces the cooldown of True Shot by 5 sec.\n(4) Set Survival: When Lacerate deals damage, it also increases all damage you deal to your Lacerate target by 2% for 12 sec.\nSell Price:" }
entries[127051] = { ["name"] = "Gladiator's Ironskin Tunic", ["text"] = "Warlords Season 1\nBinds when picked up\nChest Leather\n8 Armor\n+5 [Agility or Intellect]\n+7 Stamina\n+ 5 Critical Strike\n+ 5 Mastery\nClasses: Monk\nRequires any Horde race\nGladiator's Ironskin (0/5)\nGladiator's Ironskin Tunic\nGladiator's Ironskin Helm\nGladiator's Ironskin Gloves\nGladiator's Ironskin Spaulders\nGladiator's Ironskin Legguards\nLegacy Set: Bonus is inactive\n(2) Set Brewmaster: When you use [ Chi Torpedo / Roll], the Energy cost of your Tiger Palm is reduced by 30 for 4 sec.\n(2) Set Windwalker: Touch of Karma now has a threshold of 100% of your maximum health.\n(2) Set Mistweaver: Enveloping Mist reduces the target's chance to be hit with a critical strike by 20% for 6 sec.\n(4) Set Brewmaster: Increases the damage done by your Breath of Fire by 30%.\n(4) Set Windwalker: Storm, Earth, and Fire grants you 8% damage reduction for 20 sec. (1s cooldown)\n(4) Set Mistweaver: Reduces the cooldown of Life Cocoon by 45 sec.\nSell Price:" }
entries[127052] = { ["name"] = "Gladiator's Scaled Chestpiece", ["text"] = "Warlords Season 1\nBinds when picked up\nChest Plate\n17 Armor\n+5 [Strength or Intellect]\n+7 Stamina\n+ 5 Critical Strike\n+ 5 Haste\nClasses: Paladin\nRequires any Horde race\nGladiator's Vindication (0/5)\nGladiator's Scaled Chestpiece\nGladiator's Scaled Helm\nGladiator's Scaled Gauntlets\nGladiator's Scaled Shoulders\nGladiator's Scaled Legguards\nLegacy Set: Bonus is inactive\n(2) Set Holy: Increase the duration of Aura Mastery by 2 sec.\n(2) Set Protection: Targets hit by your [Fist][Hammer] of Justice take 10% more damage for 6 sec.\n(2) Set Retribution: When you cast Avenging Wrath, the duration of all incoming crowd control effects on yourself is reduced by 25% for 15 sec.\n(4) Set Holy: Your spell haste is increased by 2% every time you heal your Beacon of Light target. Lasts for 6 sec. Stacks up to 4 times.\n(4) Set Protection: Reduces damage taken while Ardent Defender is active by an additional 10%, and when you activate Ardent Defender, it will also apply to the nearest ally within 15 yards.\n(4) Set Retribution: Spending Holy Power increases your damage and healing by 2% per Holy Power spent for 4 sec. (500ms cooldown)\nSell Price:" }
entries[127053] = { ["name"] = "Gladiator's Leather Tunic", ["text"] = "Warlords Season 1\nBinds when picked up\nChest Leather\n8 Armor\n+5 [Agility or Intellect]\n+7 Stamina\n+ 5 Haste\n+ 5 Mastery\nClasses: Rogue\nRequires any Horde race\nGladiator's Vestments (0/5)\nGladiator's Leather Tunic\nGladiator's Leather Helm\nGladiator's Leather Gloves\nGladiator's Leather Spaulders\nGladiator's Leather Legguards\nLegacy Set: Bonus is inactive\n(2) Set Assassination: Successfully interrupting a spell with Kick generates 3 combo points. (2) Set Outlaw: Successfully interrupting a spell with Kick generates 3 combo points. (2) Set Subtlety: Successfully interrupting a spell with Kick generates 3 combo points.\n(4) Set Assassination: When you use Vanish, you gain 5 Combo Points and the critical strike chance of your next Mutilate or Envenom is increased by 10%.\n(4) Set Outlaw: When you use Vanish, you gain 5 Combo Points and the critical strike chance of your next Saber Slash, Run Through, Between the Eyes, or Ambush is increased by 100%.\n(4) Set Subtlety: Feint also increases your Versatility by 140 for 5 sec.\nSell Price:" }
entries[127054] = { ["name"] = "Gladiator's Ringmail Armor", ["text"] = "Warlords Season 1\nBinds when picked up\nChest Mail\n11 Armor\n+5 [Agility or Intellect]\n+7 Stamina\n+ 5 Critical Strike\n+ 5 Haste\nClasses: Shaman\nRequires any Horde race\nGladiator's Wartide (0/5)\nGladiator's Ringmail Armor\nGladiator's Ringmail Helm\nGladiator's Ringmail Gauntlets\nGladiator's Ringmail Spaulders\nGladiator's Ringmail Leggings\nLegacy Set: Bonus is inactive\n(2) Set Elemental: Reduces the cooldown of Hex by 15 sec.\n(2) Set Enhancement: When you activate Feral Spirits, the duration of incoming crowd control effects is reduced by 25% for 30 sec.\n(2) Set Restoration: When you dispel a harmful Magic or Curse effect from an ally, they gain 150 Versatility for 10 sec.\n(4) Set Elemental: For 15 sec following the summon of an Elemental, you are immune to silence and interupt effects.\n(4) Set Enhancement: Windfury now deals damage 2 extra times.\n(4) Set Restoration: When the target of your Riptide effect drops below 50% health, the duration is refreshed.\nSell Price:" }
entries[127055] = { ["name"] = "Gladiator's Plate Chestpiece", ["text"] = "Warlords Season 1\nBinds when picked up\nChest Plate\n17 Armor\n+5 [Strength or Intellect]\n+7 Stamina\n+ 5 Critical Strike\n+ 5 Mastery\nClasses: Warrior\nRequires any Horde race\nGladiator's Battlegear (0/5)\nGladiator's Plate Chestpiece\nGladiator's Plate Helm\nGladiator's Plate Gauntlets\nGladiator's Plate Shoulders\nGladiator's Plate Legguards\nLegacy Set: Bonus is inactive\n(2) Set Arms: When you use Charge, the critical strike chance of your next Mortal Strike is increased by 50%.\n(2) Set Fury: When you use Charge, the critical strike chance of your next Bloodthirst is increased by 50%.\n(2) Set Protection: When you use Intercept, the critical strike chance of your next Shield Slam is increased by 50%.\n(4) Set Arms: You now generate Rage from taking damage. (4) Set Fury: You now generate Rage from taking damage. (4) Set Protection: You now generate Rage from taking damage.\nSell Price:" }
entries[127063] = { ["name"] = "Gladiator's Dragonhide Robes", ["text"] = "Warlords Season 1\nBinds when picked up\nChest Leather\n8 Armor\n+5 [Agility or Intellect]\n+7 Stamina\n+ 5 Haste\n+ 5 Mastery\nClasses: Druid\nRequires any Horde race\nGladiator's Sanctuary (0/5)\nGladiator's Dragonhide Robes\nGladiator's Dragonhide Helm\nGladiator's Dragonhide Gloves\nGladiator's Dragonhide Spaulders\nGladiator's Dragonhide Legguards\nLegacy Set: Bonus is inactive\n(2) Set Balance: Increases the damage bonus from Lunar and Solar Empowerments by 4%.\n(2) Set Feral: Interrupting a spell with Skull Bash resets the cooldown of Tiger's Fury.\n(2) Set Guardian: If you hit a player with Mangle while they are casting or channeling a spell, their damage and healing will be reduced by 35% for 3 sec.\n(2) Set Restoration: Your Ironbark now also grants the target Nature's Grasp, which roots the first 2 attackers for 6 sec.\n(4) Set Balance: When Starsurge hits a player, the cast time of Lunar Strike is reduced by 30%, and the damage of Solar Wrath is increased by 30% for 6 sec.\n(4) Set Feral: Shred critical strikes causes the target to take 10% increased damage from your bleed effects for 6 sec.\n(4) Set Guardian: While Survival Instincts is active, 35% of the direct damage you deal will heal the 2 nearest allies.\n(4) Set Restoration: Increases the periodic healing of Lifebloom by 15%.\nSell Price:" }
entries[127064] = { ["name"] = "Gladiator's Silk Robe", ["text"] = "Warlords Season 1\nBinds when picked up\nChest Cloth\n4 Armor\n+5 Intellect\n+7 Stamina\n+ 5 Critical Strike\n+ 5 Mastery\nClasses: Mage\nRequires any Horde race\nGladiator's Regalia (0/5)\nGladiator's Silk Robe\nGladiator's Silk Cowl\nGladiator's Silk Handguards\nGladiator's Silk Amice\nGladiator's Silk Trousers\nLegacy Set: Bonus is inactive\n(2) Set Arcane: Successfully Spellstealing a buff generates a use of Arcane Missiles.\n(2) Set Fire: Casting Scorch reduces the cast time and increases the critical strike chance of Fireball by 15%, stacking up to 3 times.\n(2) Set Frost: When you cast Cone of Cold, a patch of ice is left on the ground below the target area for 6 sec, slowing any enemies in the area by 50%.\n(4) Set Arcane: While Arcane Power is active, you can cast Arcane Blast and Arcane Missiles while moving.\n(4) Set Fire: When you consume Hot Streak, your Pyroblast target has a 15% increased chance to be critically hit by your Fireball spell for 10 sec.\n(4) Set Frost: Frostbolt deals 50% increased damage to snared targets.\nSell Price:" }
entries[127065] = { ["name"] = "Gladiator's Satin Robe", ["text"] = "Warlords Season 1\nBinds when picked up\nChest Cloth\n4 Armor\n+5 Intellect\n+7 Stamina\n+ 5 Critical Strike\n+ 5 Mastery\nClasses: Priest\nRequires any Horde race\nGladiator's Investiture (0/5)\nGladiator's Satin Robe\nGladiator's Satin Hood\nGladiator's Satin Gloves\nGladiator's Satin Mantle\nGladiator's Satin Leggings\nLegacy Set: Bonus is inactive\n(2) Set Discipline: Penance now increases the movement speed of a friendly target you heal by 30%, and decreases the movement speed of an enemy target you damage by 50%.\n(2) Set Holy: When Prayer of Mending heals a target, you and the target gain 20 Versatility for 10 sec. Stacks up to 5 times.\n(2) Set Shadow: When Dispersion ends, you gain 300 Versatility for 10 sec.\n(4) Set Discipline: Reduces the cooldown of Pain Suppression by 60 sec.\n(4) Set Holy: Reduces the cooldown of Guardian Spirit by 60 sec.\n(4) Set Shadow: When you use Silence, you gain 30 Insanity.\nSell Price:" }
entries[127066] = { ["name"] = "Gladiator's Felweave Raiment", ["text"] = "Warlords Season 1\nBinds when picked up\nChest Cloth\n4 Armor\n+5 Intellect\n+7 Stamina\n+ 5 Critical Strike\n+ 5 Haste\nClasses: Warlock\nRequires any Horde race\nGladiator's Felshroud (0/5)\nGladiator's Felweave Raiment\nGladiator's Felweave Cowl\nGladiator's Felweave Handguards\nGladiator's Felweave Amice\nGladiator's Felweave Trousers\nLegacy Set: Bonus is inactive\n(2) Set Affliction: Getting stunned, silenced, interrupted, or feared generates 1 Soul Shard. Can only occur once every 15 sec. (15s cooldown)\n(2) Set Demonology: When you or your pet are below 20% of maximum health, you gain 200 Versatility.\n(2) Set Destruction: Getting stunned, silenced, interrupted, or feared generates 1 Soul Shard. Can only occur once every 15 sec. (15s cooldown)\n(4) Set Affliction: After using Demonic Circle: Teleport, you gain 200 Versatility for 10 sec. (15s cooldown)\n(4) Set Demonology: Increases healing done by Soul Link by 5%.\n(4) Set Destruction: Increases damage done by Incinerate on targets afflicted by your Immolate by 50%.\nSell Price:" }
entries[127071] = { ["name"] = "Gladiator's Dreadplate Helm", ["text"] = "Warlords Season 1\nBinds when picked up\nHead Plate\n13 Armor\n+5 [Strength or Intellect]\n+7 Stamina\n+ 5 Critical Strike\n+ 5 Mastery\nClasses: Death Knight\nRequires any Horde race\nGladiator's Desecration (0/5)\nGladiator's Dreadplate Chestpiece\nGladiator's Dreadplate Helm\nGladiator's Dreadplate Gauntlets\nGladiator's Dreadplate Shoulders\nGladiator's Dreadplate Legguards\n(2) Set Blood: Using Death Grip increases the damage of your next weapon special attack by 25%. (2) Set Frost: Using Death Grip increases the damage of your next weapon special attack by 25%. (2) Set Unholy: Using Death Grip increases the damage of your next weapon special attack by 25%.\n(4) Set Blood: Anti-Magic Shell also applies to the nearest ally.\n(4) Set Frost: When you have Rime active, your next Howling Blast will increase Frost damage taken on all targets by 10% for 8 sec.\n(4) Set Unholy: When you activate Dark Transformation, your Shadow damage dealt is increased by 20% for 15 sec.\nSell Price:" }
entries[127072] = { ["name"] = "Gladiator's Dragonhide Helm", ["text"] = "Warlords Season 1\nBinds when picked up\nHead Leather\n6 Armor\n+5 [Agility or Intellect]\n+7 Stamina\n+ 5 Haste\n+ 5 Mastery\nClasses: Druid\nRequires any Horde race\nGladiator's Sanctuary (0/5)\nGladiator's Dragonhide Robes\nGladiator's Dragonhide Helm\nGladiator's Dragonhide Gloves\nGladiator's Dragonhide Spaulders\nGladiator's Dragonhide Legguards\nLegacy Set: Bonus is inactive\n(2) Set Balance: Increases the damage bonus from Lunar and Solar Empowerments by 4%.\n(2) Set Feral: Interrupting a spell with Skull Bash resets the cooldown of Tiger's Fury.\n(2) Set Guardian: If you hit a player with Mangle while they are casting or channeling a spell, their damage and healing will be reduced by 35% for 3 sec.\n(2) Set Restoration: Your Ironbark now also grants the target Nature's Grasp, which roots the first 2 attackers for 6 sec.\n(4) Set Balance: When Starsurge hits a player, the cast time of Lunar Strike is reduced by 30%, and the damage of Solar Wrath is increased by 30% for 6 sec.\n(4) Set Feral: Shred critical strikes causes the target to take 10% increased damage from your bleed effects for 6 sec.\n(4) Set Guardian: While Survival Instincts is active, 35% of the direct damage you deal will heal the 2 nearest allies.\n(4) Set Restoration: Increases the periodic healing of Lifebloom by 15%.\nSell Price:" }
entries[127073] = { ["name"] = "Gladiator's Chain Helm", ["text"] = "Warlords Season 1\nBinds when picked up\nHead Mail\n8 Armor\n+5 [Agility or Intellect]\n+7 Stamina\n+ 5 Critical Strike\n+ 5 Mastery\nClasses: Hunter\nRequires any Horde race\nGladiator's Pursuit (0/5)\nGladiator's Chain Armor\nGladiator's Chain Helm\nGladiator's Chain Gauntlets\nGladiator's Chain Spaulders\nGladiator's Chain Leggings\nLegacy Set: Bonus is inactive\n(2) Set Beast Mastery: Increases the duration of [ Wing Clip / Concussive Shot] by 2 sec. (2) Set Marksmanship: Increases the duration of [ Wing Clip / Concussive Shot] by 2 sec. (2) Set Survival: Increases the duration of [ Wing Clip / Concussive Shot] by 2 sec.\n(4) Set Beast Mastery: You and your pet share diminishing returns from crowd control effects.\n(4) Set Marksmanship: Aimed Shot reduces the cooldown of True Shot by 5 sec.\n(4) Set Survival: When Lacerate deals damage, it also increases all damage you deal to your Lacerate target by 2% for 12 sec.\nSell Price:" }
entries[127074] = { ["name"] = "Gladiator's Silk Cowl", ["text"] = "Warlords Season 1\nBinds when picked up\nHead Cloth\n3 Armor\n+5 Intellect\n+7 Stamina\n+ 5 Critical Strike\n+ 5 Mastery\nClasses: Mage\nRequires any Horde race\nGladiator's Regalia (0/5)\nGladiator's Silk Robe\nGladiator's Silk Cowl\nGladiator's Silk Handguards\nGladiator's Silk Amice\nGladiator's Silk Trousers\nLegacy Set: Bonus is inactive\n(2) Set Arcane: Successfully Spellstealing a buff generates a use of Arcane Missiles.\n(2) Set Fire: Casting Scorch reduces the cast time and increases the critical strike chance of Fireball by 15%, stacking up to 3 times.\n(2) Set Frost: When you cast Cone of Cold, a patch of ice is left on the ground below the target area for 6 sec, slowing any enemies in the area by 50%.\n(4) Set Arcane: While Arcane Power is active, you can cast Arcane Blast and Arcane Missiles while moving.\n(4) Set Fire: When you consume Hot Streak, your Pyroblast target has a 15% increased chance to be critically hit by your Fireball spell for 10 sec.\n(4) Set Frost: Frostbolt deals 50% increased damage to snared targets.\nSell Price:" }
entries[127075] = { ["name"] = "Gladiator's Ironskin Helm", ["text"] = "Warlords Season 1\nBinds when picked up\nHead Leather\n6 Armor\n+5 [Agility or Intellect]\n+7 Stamina\n+ 5 Critical Strike\n+ 5 Haste\nClasses: Monk\nRequires any Horde race\nGladiator's Ironskin (0/5)\nGladiator's Ironskin Tunic\nGladiator's Ironskin Helm\nGladiator's Ironskin Gloves\nGladiator's Ironskin Spaulders\nGladiator's Ironskin Legguards\nLegacy Set: Bonus is inactive\n(2) Set Brewmaster: When you use [ Chi Torpedo / Roll], the Energy cost of your Tiger Palm is reduced by 30 for 4 sec.\n(2) Set Windwalker: Touch of Karma now has a threshold of 100% of your maximum health.\n(2) Set Mistweaver: Enveloping Mist reduces the target's chance to be hit with a critical strike by 20% for 6 sec.\n(4) Set Brewmaster: Increases the damage done by your Breath of Fire by 30%.\n(4) Set Windwalker: Storm, Earth, and Fire grants you 8% damage reduction for 20 sec. (1s cooldown)\n(4) Set Mistweaver: Reduces the cooldown of Life Cocoon by 45 sec.\nSell Price:" }
entries[127076] = { ["name"] = "Gladiator's Scaled Helm", ["text"] = "Warlords Season 1\nBinds when picked up\nHead Plate\n13 Armor\n+5 [Strength or Intellect]\n+7 Stamina\n+ 5 Haste\n+ 5 Mastery\nClasses: Paladin\nRequires any Horde race\nGladiator's Vindication (0/5)\nGladiator's Scaled Chestpiece\nGladiator's Scaled Helm\nGladiator's Scaled Gauntlets\nGladiator's Scaled Shoulders\nGladiator's Scaled Legguards\nLegacy Set: Bonus is inactive\n(2) Set Holy: Increase the duration of Aura Mastery by 2 sec.\n(2) Set Protection: Targets hit by your [Fist][Hammer] of Justice take 10% more damage for 6 sec.\n(2) Set Retribution: When you cast Avenging Wrath, the duration of all incoming crowd control effects on yourself is reduced by 25% for 15 sec.\n(4) Set Holy: Your spell haste is increased by 2% every time you heal your Beacon of Light target. Lasts for 6 sec. Stacks up to 4 times.\n(4) Set Protection: Reduces damage taken while Ardent Defender is active by an additional 10%, and when you activate Ardent Defender, it will also apply to the nearest ally within 15 yards.\n(4) Set Retribution: Spending Holy Power increases your damage and healing by 2% per Holy Power spent for 4 sec. (500ms cooldown)\nSell Price:" }
entries[127077] = { ["name"] = "Gladiator's Satin Hood", ["text"] = "Warlords Season 1\nBinds when picked up\nHead Cloth\n3 Armor\n+5 Intellect\n+7 Stamina\n+ 5 Haste\n+ 5 Mastery\nClasses: Priest\nRequires any Horde race\nGladiator's Investiture (0/5)\nGladiator's Satin Robe\nGladiator's Satin Hood\nGladiator's Satin Gloves\nGladiator's Satin Mantle\nGladiator's Satin Leggings\nLegacy Set: Bonus is inactive\n(2) Set Discipline: Penance now increases the movement speed of a friendly target you heal by 30%, and decreases the movement speed of an enemy target you damage by 50%.\n(2) Set Holy: When Prayer of Mending heals a target, you and the target gain 20 Versatility for 10 sec. Stacks up to 5 times.\n(2) Set Shadow: When Dispersion ends, you gain 300 Versatility for 10 sec.\n(4) Set Discipline: Reduces the cooldown of Pain Suppression by 60 sec.\n(4) Set Holy: Reduces the cooldown of Guardian Spirit by 60 sec.\n(4) Set Shadow: When you use Silence, you gain 30 Insanity.\nSell Price:" }
entries[127078] = { ["name"] = "Gladiator's Leather Helm", ["text"] = "Warlords Season 1\nBinds when picked up\nHead Leather\n6 Armor\n+5 [Agility or Intellect]\n+7 Stamina\n+ 5 Critical Strike\n+ 5 Mastery\nClasses: Rogue\nRequires any Horde race\nGladiator's Vestments (0/5)\nGladiator's Leather Tunic\nGladiator's Leather Helm\nGladiator's Leather Gloves\nGladiator's Leather Spaulders\nGladiator's Leather Legguards\nLegacy Set: Bonus is inactive\n(2) Set Assassination: Successfully interrupting a spell with Kick generates 3 combo points. (2) Set Outlaw: Successfully interrupting a spell with Kick generates 3 combo points. (2) Set Subtlety: Successfully interrupting a spell with Kick generates 3 combo points.\n(4) Set Assassination: When you use Vanish, you gain 5 Combo Points and the critical strike chance of your next Mutilate or Envenom is increased by 10%.\n(4) Set Outlaw: When you use Vanish, you gain 5 Combo Points and the critical strike chance of your next Saber Slash, Run Through, Between the Eyes, or Ambush is increased by 100%.\n(4) Set Subtlety: Feint also increases your Versatility by 140 for 5 sec.\nSell Price:" }
entries[127079] = { ["name"] = "Gladiator's Ringmail Helm", ["text"] = "Warlords Season 1\nBinds when picked up\nHead Mail\n8 Armor\n+5 [Agility or Intellect]\n+7 Stamina\n+ 5 Haste\n+ 5 Mastery\nClasses: Shaman\nRequires any Horde race\nGladiator's Wartide (0/5)\nGladiator's Ringmail Armor\nGladiator's Ringmail Helm\nGladiator's Ringmail Gauntlets\nGladiator's Ringmail Spaulders\nGladiator's Ringmail Leggings\nLegacy Set: Bonus is inactive\n(2) Set Elemental: Reduces the cooldown of Hex by 15 sec.\n(2) Set Enhancement: When you activate Feral Spirits, the duration of incoming crowd control effects is reduced by 25% for 30 sec.\n(2) Set Restoration: When you dispel a harmful Magic or Curse effect from an ally, they gain 150 Versatility for 10 sec.\n(4) Set Elemental: For 15 sec following the summon of an Elemental, you are immune to silence and interupt effects.\n(4) Set Enhancement: Windfury now deals damage 2 extra times.\n(4) Set Restoration: When the target of your Riptide effect drops below 50% health, the duration is refreshed.\nSell Price:" }
entries[127080] = { ["name"] = "Gladiator's Felweave Cowl", ["text"] = "Warlords Season 1\nBinds when picked up\nHead Cloth\n3 Armor\n+5 Intellect\n+7 Stamina\n+ 5 Critical Strike\n+ 5 Haste\nClasses: Warlock\nRequires any Horde race\nGladiator's Felshroud (0/5)\nGladiator's Felweave Raiment\nGladiator's Felweave Cowl\nGladiator's Felweave Handguards\nGladiator's Felweave Amice\nGladiator's Felweave Trousers\nLegacy Set: Bonus is inactive\n(2) Set Affliction: Getting stunned, silenced, interrupted, or feared generates 1 Soul Shard. Can only occur once every 15 sec. (15s cooldown)\n(2) Set Demonology: When you or your pet are below 20% of maximum health, you gain 200 Versatility.\n(2) Set Destruction: Getting stunned, silenced, interrupted, or feared generates 1 Soul Shard. Can only occur once every 15 sec. (15s cooldown)\n(4) Set Affliction: After using Demonic Circle: Teleport, you gain 200 Versatility for 10 sec. (15s cooldown)\n(4) Set Demonology: Increases healing done by Soul Link by 5%.\n(4) Set Destruction: Increases damage done by Incinerate on targets afflicted by your Immolate by 50%.\nSell Price:" }
